using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OpenAlex.Data; using OpenAlex.Data.Models;
namespace OpenAlex.Web.Pages.Admin;
[Authorize(Policy="AdminPolicy")]
public sealed class RolesModel:PageModel{private readonly RoleManagementRepository _repository; public RolesModel(RoleManagementRepository repository)=>_repository=repository; public IReadOnlyList<RoleManagementUser> Users{get;private set;}=Array.Empty<RoleManagementUser>(); [TempData] public string? Message{get;set;} public async Task OnGetAsync(CancellationToken ct){Users=await _repository.GetUsersAsync(ct);} public async Task<IActionResult> OnPostToggleEnabledAsync(long id,bool enabled,CancellationToken ct){try{await _repository.SetUserEnabledAsync(id,enabled,GetAdminName(),"Changed from role-management UI.",ct); Message=enabled?"User enabled.":"User disabled.";}catch(Exception ex){Message=ex.Message;} return RedirectToPage();} string GetAdminName()=>User?.Identity?.IsAuthenticated==true&&!string.IsNullOrWhiteSpace(User.Identity.Name)?User.Identity.Name!:"local.demo.admin";}
